public class InnerPrivateConnectionConnectionConfigurationFactory(Action<Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration>
{

    internal InnerPrivateConnectionSelfManagedModeFactory SelfManagedFactory { get; set; }

    internal InnerPrivateConnectionServiceManagedModeFactory ServiceManagedFactory { get; set; }

    protected override Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration Create()
    {
        var connectionConfigurationResult = CreateConnectionConfiguration();
        factoryAction?.Invoke(connectionConfigurationResult);

        return connectionConfigurationResult;
    }

    private Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration CreateConnectionConfiguration()
    {
        var connectionConfigurationResult = new Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration();

        return connectionConfigurationResult;
    }
    public override void CreateChildren(Humidifier.DevOpsAgent.PrivateConnectionTypes.ConnectionConfiguration result)
    {
        base.CreateChildren(result);

        result.SelfManaged ??= SelfManagedFactory?.Build();
        result.ServiceManaged ??= ServiceManagedFactory?.Build();
    }

} // End Of Class

